-- Issue #4423 Wave 4b batch 1: messaging, conversations, notifications and team tables.
-- 57 policies on 13 tables. Generated by
-- scripts/db/issue-4423-rls-initplan.mjs from production pg_policies.
--
-- Each policy keeps its roles, command and permissive/restrictive mode
-- (ALTER POLICY changes only the clauses it names). In USING / WITH CHECK
-- the only change is that each auth.*() / current_setting() call is
-- wrapped as a scalar sub-select, which Postgres evaluates once per
-- statement instead of once per row. Same value, same rows.
--
-- Locks: ALTER POLICY holds an ACCESS EXCLUSIVE lock on its table until
-- COMMIT. lock_timeout makes the file fail fast (55P03) instead of
-- queueing readers on every table it already altered behind one long
-- reader. On 55P03 re-run the file a minute later; it is idempotent.
-- Exact rollback: generated from production state at apply time; see the
-- private rollback pack (this script writes batchN.rollback.sql).

BEGIN;
SET LOCAL lock_timeout = '3s';
-- Names resolve exactly as they did when pg_policies printed them.
SET LOCAL search_path = public;

ALTER POLICY "conversation_participant_lifecycle_owner_select" ON public."conversation_participant_lifecycle"
  USING ((user_id = ( SELECT auth.uid() AS uid)));

ALTER POLICY "conversation_participants_brand_enquiry_update_guard" ON public."conversation_participants"
  USING (issue_4111_participant_row_allowed(conversation_id, ( SELECT auth.uid() AS uid)))
  WITH CHECK (issue_4111_participant_row_allowed(conversation_id, ( SELECT auth.uid() AS uid)));

ALTER POLICY "conversation_participants_brand_group_read" ON public."conversation_participants"
  USING (issue_3720_brand_group_can_access(conversation_id, ( SELECT auth.uid() AS uid)));

ALTER POLICY "conversation_participants_brand_team_member_delete" ON public."conversation_participants"
