ALTER POLICY "conversation_participants_brand_team_member_read" ON public."conversation_participants"
  USING (is_conversation_brand_team_member(conversation_id, ( SELECT auth.uid() AS uid)));

ALTER POLICY "conversation_participants_direct_self_add" ON public."conversation_participants"
