ALTER POLICY "Users can update their own participation" ON public."conversation_participants"
  USING ((user_id = ( SELECT auth.uid() AS uid)))
  WITH CHECK ((user_id = ( SELECT auth.uid() AS uid)));

ALTER POLICY "Users can view participants in their conversations" ON public."conversation_participants"
  USING (((user_id = ( SELECT auth.uid() AS uid)) OR is_conversation_participant(conversation_id, ( SELECT auth.uid() AS uid))));

ALTER POLICY "conversation_presence_support_staff_read" ON public."conversation_presence"
  USING (((EXISTS ( SELECT 1
   FROM conversations c
  WHERE ((c.id = conversation_presence.conversation_id) AND (c.linked_entity_type = 'support'::text)))) AND (is_support_staff(( SELECT auth.uid() AS uid)) OR is_admin_user())));

ALTER POLICY "Participants can read conversation presence" ON public."conversation_presence"
  USING ((EXISTS ( SELECT 1
   FROM conversation_participants cp
  WHERE ((cp.conversation_id = conversation_presence.conversation_id) AND (cp.user_id = ( SELECT auth.uid() AS uid))))));

ALTER POLICY "Users can update own presence" ON public."conversation_presence"
  USING ((( SELECT auth.uid() AS uid) = user_id))
  WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));

ALTER POLICY "Users can upsert own presence" ON public."conversation_presence"
  WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));

ALTER POLICY "conversations_brand_enquiry_read" ON public."conversations"
  USING (((linked_entity_type = 'brand_enquiry'::text) AND issue_4111_enquiry_can_read(id, ( SELECT auth.uid() AS uid))));

ALTER POLICY "conversations_brand_group_read" ON public."conversations"
  USING (((linked_entity_type = 'brand'::text) AND issue_3720_brand_group_can_access(id, ( SELECT auth.uid() AS uid))));

ALTER POLICY "conversations_brand_support_read" ON public."conversations"
  USING (((linked_entity_type = 'support'::text) AND (EXISTS ( SELECT 1
   FROM support_tickets ticket
  WHERE ((ticket.conversation_id = conversations.id) AND (ticket.visibility = 'brand'::text) AND issue_4382_is_brand_member(ticket.brand_id, ( SELECT auth.uid() AS uid)))))));

ALTER POLICY "conversations_brand_team_member_read" ON public."conversations"
  USING (((linked_entity_type = ANY (ARRAY['trip'::text, 'event'::text])) AND (event_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM (brand_team_members btm
     JOIN events e ON ((e.brand_id = btm.brand_id)))
  WHERE ((e.id = conversations.event_id) AND (btm.user_id = ( SELECT auth.uid() AS uid)) AND (btm.accepted_at IS NOT NULL) AND (btm.removed_at IS NULL))))));

ALTER POLICY "conversations_brand_team_member_update" ON public."conversations"
  USING (((linked_entity_type = ANY (ARRAY['trip'::text, 'event'::text])) AND (event_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM (brand_team_members btm
     JOIN events e ON ((e.brand_id = btm.brand_id)))
  WHERE ((e.id = conversations.event_id) AND (btm.user_id = ( SELECT auth.uid() AS uid)) AND (btm.accepted_at IS NOT NULL) AND (btm.removed_at IS NULL))))))
  WITH CHECK (((linked_entity_type = ANY (ARRAY['trip'::text, 'event'::text])) AND (event_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM (brand_team_members btm
     JOIN events e ON ((e.brand_id = btm.brand_id)))
  WHERE ((e.id = conversations.event_id) AND (btm.user_id = ( SELECT auth.uid() AS uid)) AND (btm.accepted_at IS NOT NULL) AND (btm.removed_at IS NULL))))));

ALTER POLICY "conversations_support_staff_read" ON public."conversations"
  USING (((linked_entity_type = 'support'::text) AND (is_support_staff(( SELECT auth.uid() AS uid)) OR is_admin_user())));

ALTER POLICY "Users can create conversations" ON public."conversations"
  WITH CHECK ((created_by = ( SELECT auth.uid() AS uid)));

ALTER POLICY "Users can view conversations they participate in" ON public."conversations"
  USING ((((created_by = ( SELECT auth.uid() AS uid)) OR is_conversation_participant(id, ( SELECT auth.uid() AS uid))) AND (linked_entity_type IS DISTINCT FROM 'support'::text)));

ALTER POLICY "Users can view their conversations" ON public."conversations"
  USING ((is_conversation_participant(id, ( SELECT auth.uid() AS uid)) AND (linked_entity_type IS DISTINCT FROM 'support'::text)));

ALTER POLICY "message_media_views_read_own" ON public."message_media_views"
