ALTER POLICY "message_reads_brand_enquiry_reader_update" ON public."message_reads"
  USING (issue_4111_read_receipt_allowed(message_id, ( SELECT auth.uid() AS uid)))
  WITH CHECK (issue_4111_read_receipt_allowed(message_id, ( SELECT auth.uid() AS uid)));

ALTER POLICY "Users can mark messages as read" ON public."message_reads"
  USING ((user_id = ( SELECT auth.uid() AS uid)))
  WITH CHECK ((user_id = ( SELECT auth.uid() AS uid)));

ALTER POLICY "Users can view read receipts for messages" ON public."message_reads"
