   FROM (messages m
     JOIN conversation_participants cp ON ((cp.conversation_id = m.conversation_id)))
  WHERE ((m.id = message_reads.message_id) AND (cp.user_id = ( SELECT auth.uid() AS uid))))));

ALTER POLICY "messages_brand_enquiry_read" ON public."messages"
  USING (((deleted_at IS NULL) AND issue_4111_enquiry_can_read(conversation_id, ( SELECT auth.uid() AS uid))));

ALTER POLICY "messages_brand_group_read" ON public."messages"
  USING (((deleted_at IS NULL) AND issue_3720_brand_group_can_access(conversation_id, ( SELECT auth.uid() AS uid))));

ALTER POLICY "messages_brand_support_read" ON public."messages"
  USING (((deleted_at IS NULL) AND (EXISTS ( SELECT 1
   FROM support_tickets ticket
  WHERE ((ticket.conversation_id = messages.conversation_id) AND (ticket.visibility = 'brand'::text) AND issue_4382_is_brand_member(ticket.brand_id, ( SELECT auth.uid() AS uid)))))));

ALTER POLICY "messages_brand_team_member_insert" ON public."messages"
  WITH CHECK (((sender_id = ( SELECT auth.uid() AS uid)) AND is_conversation_brand_team_member(conversation_id, ( SELECT auth.uid() AS uid))));

ALTER POLICY "messages_brand_team_member_read" ON public."messages"
  USING (((deleted_at IS NULL) AND is_conversation_brand_team_member(conversation_id, ( SELECT auth.uid() AS uid))));

ALTER POLICY "messages_brand_team_member_update" ON public."messages"
  USING (is_conversation_brand_team_member(conversation_id, ( SELECT auth.uid() AS uid)))
  WITH CHECK (is_conversation_brand_team_member(conversation_id, ( SELECT auth.uid() AS uid)));

ALTER POLICY "messages_broadcast_only_enforcement" ON public."messages"
  WITH CHECK (can_insert_message_into_conversation(conversation_id, ( SELECT auth.uid() AS uid)));

ALTER POLICY "messages_history_visible_from" ON public."messages"
  USING ((NOT (EXISTS ( SELECT 1
   FROM conversation_participants cp
  WHERE ((cp.conversation_id = messages.conversation_id) AND (cp.user_id = ( SELECT auth.uid() AS uid)) AND (cp.history_visible_from IS NOT NULL) AND (messages.created_at < cp.history_visible_from))))));

ALTER POLICY "messages_support_internal_insert_guard" ON public."messages"
  WITH CHECK (((NOT is_internal) OR ((( SELECT is_support_staff(( SELECT auth.uid() AS uid)) AS is_support_staff) OR ( SELECT is_admin_user() AS is_admin_user)) AND (EXISTS ( SELECT 1
   FROM conversations c
  WHERE ((c.id = messages.conversation_id) AND (c.linked_entity_type = 'support'::text)))))));

ALTER POLICY "messages_support_internal_read_guard" ON public."messages"
  USING (((NOT is_internal) OR ( SELECT is_support_staff(( SELECT auth.uid() AS uid)) AS is_support_staff) OR ( SELECT is_admin_user() AS is_admin_user)));

ALTER POLICY "messages_support_internal_update_guard" ON public."messages"
  USING (((NOT is_internal) OR ( SELECT is_support_staff(( SELECT auth.uid() AS uid)) AS is_support_staff) OR ( SELECT is_admin_user() AS is_admin_user)))
  WITH CHECK (((NOT is_internal) OR ( SELECT is_support_staff(( SELECT auth.uid() AS uid)) AS is_support_staff) OR ( SELECT is_admin_user() AS is_admin_user)));

ALTER POLICY "messages_support_staff_insert" ON public."messages"
  WITH CHECK (((sender_id = ( SELECT auth.uid() AS uid)) AND (EXISTS ( SELECT 1
   FROM conversations c
  WHERE ((c.id = messages.conversation_id) AND (c.linked_entity_type = 'support'::text)))) AND (is_support_staff(( SELECT auth.uid() AS uid)) OR is_admin_user())));

ALTER POLICY "messages_support_staff_read" ON public."messages"
  USING (((deleted_at IS NULL) AND (EXISTS ( SELECT 1
   FROM conversations c
  WHERE ((c.id = messages.conversation_id) AND (c.linked_entity_type = 'support'::text)))) AND (is_support_staff(( SELECT auth.uid() AS uid)) OR is_admin_user())));

ALTER POLICY "Users can delete their own messages" ON public."messages"
  USING ((( SELECT auth.uid() AS uid) = sender_id));

ALTER POLICY "Users can send messages to conversations they participate in" ON public."messages"
  WITH CHECK (((sender_id = ( SELECT auth.uid() AS uid)) AND (EXISTS ( SELECT 1
   FROM conversation_participants cp
  WHERE ((cp.conversation_id = messages.conversation_id) AND (cp.user_id = ( SELECT auth.uid() AS uid))))) AND (NOT (EXISTS ( SELECT 1
   FROM blocked_users bu
  WHERE (((bu.blocker_id = ( SELECT auth.uid() AS uid)) AND (bu.blocked_id IN ( SELECT cp2.user_id
           FROM conversation_participants cp2
          WHERE ((cp2.conversation_id = messages.conversation_id) AND (cp2.user_id <> ( SELECT auth.uid() AS uid)))))) OR ((bu.blocked_id = ( SELECT auth.uid() AS uid)) AND (bu.blocker_id IN ( SELECT cp3.user_id
           FROM conversation_participants cp3
          WHERE ((cp3.conversation_id = messages.conversation_id) AND (cp3.user_id <> ( SELECT auth.uid() AS uid))))))))))));

ALTER POLICY "Users can update their own messages" ON public."messages"
  USING ((( SELECT auth.uid() AS uid) = sender_id));

ALTER POLICY "Users can view messages in conversations" ON public."messages"
  USING (((deleted_at IS NULL) AND (EXISTS ( SELECT 1
   FROM conversation_participants cp
  WHERE ((cp.conversation_id = messages.conversation_id) AND (cp.user_id = ( SELECT auth.uid() AS uid)))))));

ALTER POLICY "Users can view messages in their conversations" ON public."messages"
  USING ((EXISTS ( SELECT 1
   FROM conversation_participants cp
  WHERE ((cp.conversation_id = messages.conversation_id) AND (cp.user_id = ( SELECT auth.uid() AS uid))))));

ALTER POLICY "notification_channel_prefs_owner" ON public."notification_channel_prefs"
