ALTER POLICY "Users can delete their own preferences" ON public."notification_preferences"
  USING ((( SELECT auth.uid() AS uid) = user_id));

ALTER POLICY "Users can insert their own preferences" ON public."notification_preferences"
  WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));

ALTER POLICY "Users can read their own preferences" ON public."notification_preferences"
  USING ((( SELECT auth.uid() AS uid) = user_id));

ALTER POLICY "Users can update their own preferences" ON public."notification_preferences"
